using System;using EmberBastion;
class BadgeChecks {
 static void Check(bool x,string label){if(!x)throw new Exception(label);}
 static int Main(){try{var b=new Battle();b.Gold=1000;b.Place(0,0);b.Start();var e=new Enemy{Id=100,Kind=0,HP=1,MaxHP=1,Speed=0,Travel=128,Position=Balance.Path(128)};b.Enemies.Add(e);b.Step(1.0/60);Check((b.KillKinds&1)!=0,"sword kill");b.Units.Clear();foreach(int kind in new[]{1,2}){e=new Enemy{Id=100+kind,Kind=0,HP=1,MaxHP=1,Speed=0,Travel=128,Position=Balance.Path(128)};b.Enemies.Add(e);b.Shots.Add(new Shot{Kind=kind,Target=e.Id,Position=e.Position,Destination=e.Position,Damage=20,Speed=600,Radius=55});b.Step(1.0/60);}Check((b.KillKinds&7)==7,"three killing sources");b.Phase=Phase.Won;b.PeakAlive=86;Check(BadgeRules.Evaluate(b)==5,"team only");b.PeakAlive=35;Check(BadgeRules.Evaluate(b)==7,"three badges");b.Phase=Phase.Lost;Check(BadgeRules.Evaluate(b)==0,"no loss awards");Check(BadgeRules.Limit(0,true,false)==66&&BadgeRules.Limit(1,true,false)==67&&BadgeRules.Limit(2,true,false)==65,"challenge limits");Check(BadgeRules.Limit(0,true,false,true)==51&&BadgeRules.Limit(1,true,false,true)==50&&BadgeRules.Limit(2,true,false,true)==47,"legacy challenge limits");var fire=new Battle();fire.Place(0,0);fire.Start();fire.Units.Clear();fire.Enemies.Add(new Enemy{Id=700,Kind=0,HP=.01,MaxHP=1,Burn=1,Speed=0,Travel=128,Position=Balance.Path(128)});fire.Step(1.0/60);Check(fire.KillKinds==4,"burn credits bomber");var skill=new Battle();skill.Place(0,0);skill.Start();skill.Units.Clear();skill.Enemies.Add(new Enemy{Id=701,Kind=0,HP=1,MaxHP=1,Speed=0,Travel=128,Position=Balance.Path(128)});Check(skill.Ember(Balance.Path(128)),"ember target");skill.Step(1.0/60);Check(skill.KillKinds==0,"ember does not count as unit kill");var live=new Battle();live.Place(1,0);live.Start();for(int i=0;i<5000&&live.KillKinds==0;i++)live.Step(1.0/60);Check(live.KillKinds!=0,"natural kill recorded");var restored=Battle.ImportCombat(live.ExportCombat());Check(restored.KillKinds==live.KillKinds&&live.CopyCombat().KillKinds==live.KillKinds,"kill contribution survives save and retry");var old=live.ExportCombat();old.killKinds=0;Check(Battle.ImportCombat(old).KillKinds==0,"legacy save remains unknown");Console.WriteLine("PASS kill sources, save, retry, legacy and badge thresholds");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
}


